package com.pharmnote.study;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;

/** Opens a GitHub release in the browser; Android owns install approval/signature checks. */
final class UpdateChecker {
 private static volatile boolean running;
 static android.content.SharedPreferences prefs(Activity a){return a.getSharedPreferences("updates",Context.MODE_PRIVATE);}
 static String repository(Activity a){return prefs(a).getString("repository",BuildConfig.RELEASE_REPOSITORY);}
 static boolean valid(String s){return s!=null&&s.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+");}
 static void configure(Activity a){EditText input=new EditText(a);input.setSingleLine(true);input.setHint("owner/repository");input.setText(repository(a));LinearLayout v=new LinearLayout(a);v.setOrientation(LinearLayout.VERTICAL);int p=(int)(20*a.getResources().getDisplayMetrics().density);v.setPadding(p,p,p,p);TextView help=new TextView(a);help.setText("ใส่ repo ที่เผยแพร่ APK เช่น pharmdever/pharmnote-android\nตรวจอัปเดตผ่าน API ได้เมื่อ repo เป็น public ส่วน private ให้เปิดหน้า Releases และลงชื่อเข้า GitHub");v.addView(help);v.addView(input);AlertDialog d=new AlertDialog.Builder(a).setTitle("แหล่งอัปเดต GitHub").setView(v).setNegativeButton("ยกเลิก",null).setPositiveButton("บันทึก",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(b->{String repo=input.getText().toString().trim();if(!valid(repo)){input.setError("ใส่ชื่อแบบ owner/repository");return;}prefs(a).edit().putString("repository",repo).remove("lastCheck").remove("notified").apply();d.dismiss();check(a,true);}));d.show();}
 static void check(Activity a,boolean manual){if(a.isFinishing()||a.isDestroyed())return;String repo=repository(a);if(!valid(repo)){if(manual)configure(a);return;}if(running)return;long now=System.currentTimeMillis();if(!manual&&now-prefs(a).getLong("lastCheck",0)<86400000L)return;running=true;if(manual)Toast.makeText(a,"กำลังตรวจสอบอัปเดต…",Toast.LENGTH_SHORT).show();new Thread(()->{try{JSONObject release=new JSONObject(get("https://api.github.com/repos/"+repo+"/releases/latest"));String releasePage=release.getString("html_url");if(!releasePage.startsWith("https://github.com/"+repo+"/releases/"))throw new IOException("Invalid release origin");JSONArray assets=release.getJSONArray("assets");String manifest=null;boolean apk=false;for(int i=0;i<assets.length();i++){JSONObject asset=assets.getJSONObject(i);if("update.json".equals(asset.optString("name")))manifest=asset.optString("browser_download_url");if("Pharmnote.apk".equals(asset.optString("name")))apk=true;}if(manifest==null||!apk||!manifest.startsWith("https://github.com/"+repo+"/releases/download/"))throw new IOException("Missing signed release assets");JSONObject update=new JSONObject(get(manifest));int latest=update.getInt("versionCode");if(!a.getPackageName().equals(update.getString("applicationId")))throw new IOException("Wrong application ID");int minSdk=update.getInt("minSdk");prefs(a).edit().putLong("lastCheck",System.currentTimeMillis()).apply();a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;if(latest<=BuildConfig.VERSION_CODE){if(manual)Toast.makeText(a,"คุณใช้เวอร์ชันล่าสุดแล้ว ("+BuildConfig.VERSION_NAME+")",Toast.LENGTH_LONG).show();return;}if(!manual&&prefs(a).getInt("notified",0)==latest)return;if(Build.VERSION.SDK_INT<minSdk){if(manual)new AlertDialog.Builder(a).setMessage("รุ่นใหม่ต้องใช้ Android API "+minSdk+" ขึ้นไป เครื่องนี้ยังใช้รุ่นปัจจุบันได้").setPositiveButton("ปิด",null).show();return;}prefs(a).edit().putInt("notified",latest).apply();new AlertDialog.Builder(a).setTitle("มี Pharmnote รุ่นใหม่ "+update.optString("versionName")).setMessage("ดาวน์โหลด Pharmnote.apk จาก GitHub Releases แล้วติดตั้งทับแอปเดิมได้ โดย Android จะตรวจลายเซ็นและให้คุณยืนยันการติดตั้ง\nไม่ต้องถอนแอปเดิม PDF และสรุปยังอยู่ ควรสำรองข้อมูลก่อนอัปเดต").setNegativeButton("ไว้ภายหลัง",null).setPositiveButton("เปิดหน้าดาวน์โหลด",(d,w)->browse(a,releasePage)).show();});}catch(Exception e){if(manual)a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;new AlertDialog.Builder(a).setTitle("ตรวจสอบอัปเดตไม่ได้").setMessage("อาจยังไม่มี Release, repo เป็น private, จำกัดจำนวนคำขอ หรือไม่มีอินเทอร์เน็ต คุณยังใช้ PDF และสรุปแบบออฟไลน์ได้").setNegativeButton("ปิด",null).setPositiveButton("เปิด GitHub Releases",(d,w)->browse(a,"https://github.com/"+repo+"/releases")).show();});}finally{running=false;}}).start();}
 static void browse(Activity a,String url){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){Toast.makeText(a,"ไม่พบเบราว์เซอร์สำหรับเปิด GitHub",Toast.LENGTH_LONG).show();}}
 private static String get(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","Pharmnote-Android");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;int total=0;while((n=in.read(b))!=-1){total+=n;if(total>1024*1024)throw new IOException("Response too large");out.write(b,0,n);}return out.toString(StandardCharsets.UTF_8.name());}}finally{c.disconnect();}}
}
